#!/bin/bash
set -eo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
VERSION="$("$ROOT/bin/version.sh")"
VERSION_CODE="$("$ROOT/bin/version-code.sh")"
PROPS="$ROOT/kursal-tauri/src-tauri/gen/android/app/tauri.properties"

[ -d "$(dirname "$PROPS")" ] || {
    echo "error: android project missing, run 'tauri android init'" >&2
    exit 1
}

cat >"$PROPS" <<EOF
// THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.
tauri.android.versionName=$VERSION
tauri.android.versionCode=$VERSION_CODE
EOF

echo "==> android version $VERSION (code $VERSION_CODE)"
